mapper.select:
SELECT 
FROM sys_parameter_value AS values_table
LEFT JOIN org_organization AS organizations ON organizations.id = values_table.organization_id
WHERE values_table.parameter_key = #{key}
  AND values_table.environment_code = #{command.environment}


        AND values_table.organization_id = #{command.organizationId}


        AND values_table.organization_id IS NULL

INSERT INTO sys_parameter_value (

    parameter_key, value_type, environment_code, organization_id, parameter_value,

    is_enabled, created_by, updated_by
) VALUES (
    #{key}, #{valueType}, #{command.environment}, #{command.organizationId}, #{command.value},
    #{command.enabled}, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

mapper.update:
UPDATE sys_parameter_value
SET value_type = #{valueType}, parameter_value = #{command.value}, is_enabled = #{command.enabled}, updated_by = #{actor}, updated_at = SYSUTCDATETIME()
WHERE id = #{id} AND row_version = #{command.expectedVersion}

mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1 FROM sys_dictionary_type WHERE type_code = #{typeCode}
) THEN 1 ELSE 0 END

INSERT INTO sys_dictionary_type (

    type_code, type_name, description, is_enabled, created_by, updated_by
) VALUES (
    #{command.typeCode}, #{command.typeName}, #{command.description}, 1, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

mapper.update:
UPDATE sys_dictionary_type
SET type_name = #{command.typeName}, description = #{command.description}, is_enabled = #{command.enabled}, updated_by = #{actor}, updated_at = SYSUTCDATETIME()
WHERE id = #{typeId} AND row_version = #{command.expectedVersion}

mapper.select:
SELECT FROM sys_dictionary_item WHERE dictionary_type_id = #{typeId}
AND is_enabled = 1
ORDER BY sort_order, item_code, id

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM sys_dictionary_item
    WHERE dictionary_type_id = #{typeId} AND item_code = #{itemCode}
) THEN 1 ELSE 0 END

INSERT INTO sys_dictionary_item (

    dictionary_type_id, item_code, item_label, sort_order, is_enabled, created_by, updated_by
) VALUES (
    #{typeId}, #{command.itemCode}, #{command.itemLabel}, #{command.sortOrder}, 1, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

mapper.update:
UPDATE sys_dictionary_item
SET item_label = #{command.itemLabel}, sort_order = #{command.sortOrder}, is_enabled = #{command.enabled}, updated_by = #{actor}, updated_at = SYSUTCDATETIME()
WHERE id = #{itemId} AND row_version = #{command.expectedVersion}

mapper.select:
INSERT INTO sys_external_system
    (system_code, system_name, description, is_enabled, created_by, updated_by)
VALUES
    (#{command.systemCode}, #{command.systemName}, #{command.description}, 1, #{actor}, #{actor});
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

SELECT CASE WHEN EXISTS (
    SELECT 1 FROM sys_external_endpoint
    WHERE external_system_id = #{systemId} AND environment_code = #{command.environment}
    AND organization_id = #{command.organizationId}
        AND organization_id IS NULL
) THEN 1 ELSE 0 END
